contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // The test function: supply a callee address and calldata that will cause callee.call to fail (returning false)
    // The rule: c.forward must revert (i.e., not return) when the low-level call would fail; we observe this by
    // calling c.forward inside a try/catch and asserting that the call did not succeed.
    function run(address callee, bytes calldata data) external {
        // require that callee is a contract to make the internal call meaningful
        uint32 size;
        assembly { size := extcodesize(callee) }
        require(size > 0, "callee must be a contract");

        // Attempt to call c.forward and capture whether it reverted.
        bool succeeded;
        try c.forward(callee, data) {
            succeeded = true;
        } catch {
            succeeded = false;
        }

        // On the original P, forward uses require on the call result, so if the callee call fails
        // then c.forward must revert and succeeded must be false. The mutant M ignores the success
        // flag, so it will not revert even when the callee call fails, making succeeded true.
        assert(succeeded == false);
    }

    // Allow contract to receive Ether if needed by callee during its execution
    receive() external payable {}
}

