contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    // params: callee address and calldata to forward
    function run(address callee, bytes calldata data) public {
        // We attempt the low-level call externally to observe its success without changing c.
        (bool extSuccess, ) = callee.call(data);

        // Now invoke c.forward which should forward the same call and succeed iff extSuccess is true
        // We capture whether c.forward reverts by calling it in a try/catch via low-level .call on c
        // Use abi.encodeWithSelector to call forward(address,bytes)
        bytes memory payload = abi.encodeWithSelector(bytes4(keccak256("forward(address,bytes)")), callee, data);
        (bool forwardSuccess, ) = address(c).call(payload);

        // The distinguishing rule: the external call success must equal c.forward success.
        // On the original contract P this holds (forward succeeds iff callee.call succeeds).
        // On the mutant M it is violated because M requires the inner call to fail.
        assert(extSuccess == forwardSuccess);
    }

    // allow receiving ETH just in case callee expects value transfers in calldata scenarios
    receive() external payable {}
}

