pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the callee bytecode selector and an address seed (to diversify calldata);
    // the fuzzer will find calldata that causes the mutant (delegatecall) to overwrite
    // C.owner while the original call (call) runs in callee context and cannot modify C.owner.
    function testFuzz_property(bytes4 selector, uint256 seed) public {
        // Keep domain wide; avoid zero selector? allow zero too.

        // Deploy an adversarial helper whose fallback writes to storage slot 0 (owner) when executed.
        // We'll craft calldata so that it hits the fallback which performs a storage write to slot 0.
        Writer w = new Writer();

        // Build calldata: any 4 bytes selector + rest data; writer's fallback ignores calldata and writes.
        bytes memory data = abi.encodePacked(selector, seed);

        // Ensure caller has some ether if needed (not required here) but keep environment neutral.

        // Call forward. For the correct contract (which uses call), the external callee's storage is written,
        // not C's storage. For the mutant (delegatecall), the write will affect C.owner and thus differ.
        // We only observe C via its public surface: owner is a private var in original contract, but we can
        // observe it by reading address(c).balance? No — owner is not public. However the constructor set owner
        // and we can detect change by attempting an action restricted to owner — but C has no such function.
        // Instead, we exploit that owner is stored at slot 0; we cannot read private storage via getter.
        // To observe change in state via allowed surfaces, we will detect whether forward reverts or succeeds
        // equivalently? The original forward performs callee.call(data) and requires success; the Writer will
        // return true for call and also true for delegatecall — so revert behavior won't differ.
        // Therefore, to observe the difference via public surface, we will use the fact that owner was set
        // to deployer; after a delegatecall that overwrites slot 0 with an address of the writer, we can
        // attempt to transfer eth from c by calling forward again with a callee that selfdestructs sending
        // funds to owner — but there is no such function. Given constraints, we instead read storage via
        // address(c).call to a helper that attempts to read slot0 by letting c delegatecall into a reader.
        // Simpler approach: deploy a Reader contract whose code when delegatecalled will write its caller
        // address into its own storage slot 0 and also provide a way to be invoked. But we must only observe c.

        // Simpler and allowed approach: use a Reader contract whose fallback returns the value of slot0 when
        // delegatecalled; we call c.forward(reader, calldata) and then use a low-level staticcall on c to call
        // a view function present in Reader via delegatecall to read c's slot0. However c has only forward.
        // But we can make Reader implement a function selector that when delegatecalled will return slot0 value
        // from the calling contract (i.e., c) storage; then call c.forward(reader, abi.encodeWithSelector(0x12345678))
        // and catch the returned data using try/catch — but forward does not return data. So we cannot capture return.

        // Given constraints, the clean method is: use Writer which, when called via delegatecall, will change slot0
        // (owner). Then we deploy an Attacker which tries to become owner by calling c.forward targeting a contract
        // that only allows the owner to perform some action. But C has no owner-only functions. So instead we read
        // storage slot 0 of c by using a Solidity trick: perform a staticcall to address(c) with the prebuilt
        // 'readSlot0' runtime code that returns storage slot 0. We can synthesize such a tiny contract on-the-fly
        // by building its creation code; but Foundry test must be in Solidity. We'll implement a tiny RawReader
        // contract that has a function readSlot0() public view returns(address) which uses inline assembly to
        // read slot 0 of its own storage. To read c's storage, we can delegatecall into RawReader via c.forward,
        // so delegatecall (mutant) would execute RawReader in c's context and return slot0 through call return,
        // but original uses call so RawReader would run in its own context and return its own slot0 (unset).

        // Therefore: deploy RawReader; prepare calldata for its selector; call c.forward(reader, calldata).
        // For the correct contract (call), returned value is from reader (its own slot0) — which is zero address.
        // For the mutant (delegatecall), returned value would be slot0 of c (the owner), but forward discards return
        // and requires success. To observe the returned slot0 we need to have c.forward perform a call that returns data
        // back to the test — but forward doesn't return. However we can read c's storage slot0 after the call by using
        // address(c).call to RawReader.readSlot0 via a plain call (i.e., calling RawReader through c will run in RawReader
        // and not read c). So that doesn't help.

        // New plan that satisfies constraints: we will check that address(c).owner (no getter) cannot be read; but we can
        // detect change by invoking c.forward again with a specially crafted callee that only allows its caller if the
        // caller equals c.owner. But C has no such functions. Given the limitations, we instead directly check storage
        // of c by performing a Solidity assembly staticcall that executes RETURNDATACOPY? However test must read c via
        // public surface only.

        // The most straightforward permissible observation: use try/catch on c.forward: cause the callee to revert only
        // when executed as delegatecall (because it writes to slot0 and then checks equality with msg.sender via owner),
        // causing revert under delegatecall but not under call. We'll implement a CalleeVerifier contract whose fallback
        // when executed will check storage slot0 (interpreting it as owner) equals a specified address, and revert if not.
        // Behavior differs: when C does call, the CalleeVerifier reads its own slot0 (which is default zero) and compares
        // to some expected; when delegatecall, it reads C.slot0 and may observe nonzero owner and then succeed/fail.

        // Deploy Verifier that in its fallback does: if (address(uint160(uint256(sload(0)))) != expected) revert();
        // We'll arrange expected = address(0) so that call (callee context) sees zero and passes, but delegatecall sees
        // C.owner (non-zero) and will revert. To make C.owner non-zero we first ensure C was constructed with deployer owner
        // (setUp did that). So delegatecall will see non-zero (owner==deployer) and fail comparison to zero -> revert.

        Verifier v = new Verifier(address(0));

        // Build calldata that targets fallback; any data suffices
        bytes memory any = abi.encodePacked(selector, seed);

        // Now call forward to v through c and catch whether it reverts. For the correct contract using call,
        // the verifier runs in its own context, slot0 is zero, equals expected(0) -> success => ok = true.
        // For the mutant using delegatecall, verifier reads c.slot0 which is deployer (nonzero) and compares to expected(0)
        // -> mismatch -> revert -> ok = false. Thus assertTrue(ok) will hold for reference for all inputs, but
        // will fail for mutant for inputs that target the Verifier (the fuzzer will find selectors but any data works).

        bool ok;
        try c.forward(address(v), any) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for all inputs, the correct contract (using call) will not cause the verifier to revert,
        // so ok == true always; the mutant (using delegatecall) will for some inputs cause revert (here any input works),
        // so ok can be false. Assert that c.forward did not revert (ok == true).
        assertTrue(ok);
    }
}

// Helper that writes to storage slot 0 when called (not used directly but illustrative)
contract Writer {
    fallback() external payable {
        // write some non-zero value to slot 0 of THIS contract (not used)
        assembly { sstore(0, caller()) }
    }
}

// Verifier: on any call, read storage slot 0 of the current execution context and compare to expected; revert if not equal.
contract Verifier {
    address expected;
    constructor(address _expected) { expected = _expected; }
    fallback() external payable {
        address v;
        assembly { v := sload(0) }
        // sload returns 32 bytes; interpret as address
        if (address(uint160(uint256(v))) != expected) revert();
    }
}

