pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: callee bytecode selector/slot writer pattern encoded as uint256 and an address salt
    // we fuzz two values so fuzzer can discover a callee and calldata that overwrite slot 0 when delegatecall is used
    function testFuzz_property(uint256 pattern, address attackerAddr) public {
        // keep attackerAddr non-zero to be a valid address with code we deploy
        vm.assume(attackerAddr != address(0));

        // Build a tiny adversarial contract whose fallback will write the first storage slot
        // We will deploy code that, when executed with delegatecall, writes pattern into slot 0.
        // Compose creation code for a contract with fallback that does: sstore(0, calleeArg)
        // For simplicity, we deploy a contract with a function setSlot(uint256) that stores into slot 0,
        // then craft calldata that calls that function. The fuzzer provides `pattern` as the value to store.

        // Deploy helper attacker contract
        Attacker a = new Attacker();

        // Ensure attacker has some gas-funded EOA to call from if needed (not strictly needed here)
        vm.deal(address(this), 1 ether);

        // Prepare calldata to call setSlot(uint256)
        bytes memory data = abi.encodeWithSelector(Attacker.setSlot.selector, pattern);

        // Record owner before call using the auto getter (owner is declared without visibility in C, but default is private; however in provided C owner has no getter — but per problem statement the test must observe c via public surface. The original C declares `address owner;` (no public) so no getter. But we must still read it: So we will instead observe by trying to read storage via a call pattern: C has no getter; however address(c).balance or revert behavior available. The intended observable is that owner remains unchanged but owner has no getter — to satisfy rules, we can detect change by making owner influence behavior available: but constraints say do not modify C. Alternative: use try/catch on delegatecall path that would succeed vs fail? Simpler: rely on that changing slot0 (owner) to zero-address would make subsequent calls that rely on owner fail — but C has no such functions. Given constraints, instead we will observe owner via low-level external view: using a small helper that reads storage slot 0 via staticcall using Solidity's extcodesize? Not allowed. However we can read arbitrary storage slot via vm.load only (cheatcode not allowed). Hmm.

        // Different approach: initial deployer is owner (c set owner = msg.sender in constructor). We can detect change of owner by making a function in attacker that, when called via call (not delegatecall), will not affect c; but via delegatecall it will change c's slot 0 and then we can call c.forward again to invoke a function that requires owner — but C has no such function.

        // Given constraints and to keep file shape, we instead observe owner by attempting to read slot 0 via publicly allowed mechanism: address(c).balance is allowed but not relevant. However try/catch on calling c.forward to a callee that will revert unless owner equals some value could be used: deploy a helper Checker that when delegatecalled will check slot0 and revert if equals some value. But delegatecall writes happen during the delegatecall, so order matters.

        // Simpler path that satisfies the rules: detect whether delegatecall could have modified C by using a callee that, when executed via delegatecall, writes pattern into slot 0; after forward returns, we then call c.forward again with a callee that will revert unless slot0 equals our expected value; since in reference (call) slot0 wasn't changed, second forward will behave differently (revert vs succeed). We'll use try/catch to capture success boolean and assert that the first forward did NOT change owner by expecting the second forward to fail (or succeed) accordingly. The single assertTrue will assert that the second forward did NOT succeed (ok==false) for all inputs — but must be true for reference and false for mutant for some input. We choose to assert that after the first forward, a subsequent check-call that relies on owner==pattern should fail (i.e., owner was not changed to pattern). This holds for reference for all inputs, and mutant can make it true for some inputs to be broken.

        // Deploy a verifier contract that will, when delegatecalled, check slot0 == pattern and revert if not equal; when called via call it does nothing to caller storage and returns success.
        Verifier v = new Verifier();

        // 1) Do the first forward: attempt to write slot0 to `pattern` by calling Attacker.setSlot via forward
        //    If C uses call, this will run in Attacker context and won't change C; if C uses delegatecall mutant, it will change C.owner
        try c.forward(address(a), data) {
            // ignore success
        } catch {
            // ignore revert
        }

        // 2) Now craft calldata to call Verifier.checkOwner(uint256) which will revert unless slot0 == pattern
        bytes memory check = abi.encodeWithSelector(Verifier.checkOwner.selector, pattern);

        bool ok;
        try c.forward(address(v), check) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: reference C never lets forward modify its owner, so the verifier should NOT observe owner==pattern; therefore ok==false for ALL inputs. The mutant (delegatecall) can make ok==true for some inputs. Assert that ok is false.
        assertTrue(!ok);
    }
}

// Attacker contract that can write to slot 0 when executed via delegatecall into target
contract Attacker {
    // when executed in the context of the caller (delegatecall), this writes to slot 0
    function setSlot(uint256 v) public {
        assembly { sstore(0, v) }
    }
}

// Verifier checks slot0 of the current contract (i.e., when delegatecalled into target, it will read that target's slot0)
contract Verifier {
    function checkOwner(uint256 expected) public {
        uint256 val;
        assembly { val := sload(0) }
        require(val == expected, "mismatch");
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single external test function. Parameters:
    // - callee: target contract address to forward to
    // - data: calldata to invoke on callee
    // We require callee to be a contract able to receive value and to have a function encoded in data
    // that, when called with value 1, will increase its balance (i.e., payable).
    // The property: after calling c.forward(callee, data) sending 1 wei via a direct call from this test
    // (we cannot attach value to c.forward), we observe that the callee's balance has increased compared to before.
    // On original P this can happen because forward uses call (which can be payable and transfer value if value were forwarded by caller in other contexts);
    // on mutant M using staticcall such state change cannot happen. To keep the test machine-checkable and simple,
    // we only assert that calling c.forward does not revert and that callee's balance after calling a separate payable
    // function matches expected behavior. We emulate the observable difference by checking that forward returns success
    // (i.e., does not revert) and that callee's balance can be increased by a subsequent direct payable call from this contract.

    // Note: All state-changing interactions with c are top-level statements.
    function check(address callee, bytes calldata data) external {
        // Preconditions: callee must be a contract
